  // Beitraege-Zahl im Profilkopf = gefuellte Kacheln (vorher standen dort erfundene Zahlen).
  function zaehleKacheln(){$('#pv-n').textContent=document.querySelectorAll('#pv-grid .pv-tile:not(.empty)').length;}
