    [[wahl('taetigkeit'),'f1'],[wahl('ziel'),'f2'],[wahl('stand'),'f3']].forEach(([txt,cls],i)=>{
      if(!txt)return;const t=tl[i],neu=t.textContent!==txt;kachel(t,i,txt,cls);if(animiert&&neu)bump(t);});
