  // Empfehlung wie zuvor auf Weg C: wenig Zeit oder \u201Ewill mehr\u201C \u2192 Erstgespraech.
  const PUNKTE={
    taetigkeit:{coach:'Du verkaufst dein Wissen. Genau daf\xFCr bauen wir.',dienstleistung:'Du verkaufst eine Leistung. Die zeigen wir so, dass man sie bucht.',
      direktvertrieb:'Direktvertrieb geht, mit sauberen Aussagen. Darauf achten wir f\xFCr dich.',creator:'Als Creator passt es, wenn du daraus Anfragen machen willst.',anders:'Dein Feld kl\xE4ren wir kurz, das bekommen wir hin.'},
    stand:{'Ganz am Anfang':'Du f\xE4ngst neu an. Wir bauen von null.','Poste unregelm\xE4\xDFig':'Es gibt dich schon. Wir machen daraus ein System.','Aktiv, will mehr':'Du bist aktiv. Jetzt kommt das n\xE4chste Level.'},
    zeit:{kaum:'Wenig Zeit. Dann \xFCbernehmen wir.','1-3':'Ein bis drei Stunden. Damit l\xE4sst sich arbeiten.',mehr:'Du hast Zeit. Vieles kannst du selbst machen.'}
  };
  function mbPunkt(){const n=mbWahl().length;return n===3?'Du bringst alles mit, was es braucht.':n?'Du bringst '+n+' von 3 mit. Den Rest kl\xE4ren wir im Gespr\xE4ch.':'Was du mitbringst, kl\xE4ren wir im Gespr\xE4ch.';}
  let passtUhr=[];
  function gewaehlt(g,attr){const c=document.querySelector('#'+g+' .chip[aria-pressed=true]');return c?c.dataset[attr]:'';}
